@MainActor
public class Node: Object {
	public override init(ptr: UnsafeMutableRawPointer) { super.init(ptr: ptr) }
	public enum ProcessMode: Int, Sendable, CaseIterable {
		case inherit = 0
		case pausable = 1
		case whenPaused = 2
		case always = 3
		case disabled = 4
	}
	public enum ProcessThreadGroup: Int, Sendable, CaseIterable {
		case inherit = 0
		case mainThread = 1
		case subThread = 2
	}
	public enum PhysicsInterpolationMode: Int, Sendable, CaseIterable {
