@MainActor
public class CSGShape3D: GeometryInstance3D {
	public override init(ptr: UnsafeMutableRawPointer) { super.init(ptr: ptr) }
	public enum Operation: Int, Sendable, CaseIterable {
		case union = 0
		case intersection = 1
		case subtraction = 2
	}
	@discardableResult
	public func is_root_shape() -> Bool {
		let __ret = Host.shared.callMethod(object: ptr, method: "is_root_shape", args: [])
		return __ret.asBool()
	}
	public func set_operation(operation: CSGShape3D.Operation) {
